---@class TrailQuestCellNode
---@field DisableImage                    UnityEngine.RectTransform
---@field CatText                        UnityEngine.UI.Text
---@field CatNode                        UnityEngine.RectTransform
---@field NameText                        UnityEngine.UI.Text
---@field NoText                            UnityEngine.UI.Text @序号
---@field Bg                                UnityEngine.RectTransform @背景图
local TrailQuestCellNode = Class("TrailQuestCellNode")

function TrailQuestCellNode:__init()
    self.isLocked = true
    self.questId = nil
    self.conditions = nil
end

function TrailQuestCellNode:__delete()
    self.isLocked = nil
    self.conditions = nil
    self.questId = nil
    self.controller = nil
end

function TrailQuestCellNode:Awake()
    UIEventProxy.Create(self.Bg.gameObject).onPointerClick = function(_)
        ---直接判断是否打关卡的逻辑
        if self.isLocked then
            GameUtils.Toast(localize('请通关前置关卡'))
            return
        end
        --UIModule.CloseDialog(UIModule.CurrentScreen:LastDialog())
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self.questId , conditions = self.conditions} }, {{id = Constants.UITypeIds.UITrailStageHome},{id = Constants.UITypeIds.UITrailStageQuestDialog}})
    end
end

---FreshUI
---刷新关卡单元格
---@param seqNo number
---@param trailQuestVo TrailQuestVo
---@param isLocked boolean
---@param conditions table 关卡的过关条件
function TrailQuestCellNode:FreshUI(seqNo, trailQuestVo, isLocked, conditions)
    self.questId = checkNumber(trailQuestVo.refId)
    self.conditions = conditions
    self.isLocked = checkBool(isLocked)
    self.NoText.text = tostring(seqNo)
    self.NameText.text = trailQuestVo.name
    local imageAlterable = KTool.GetOrAddComponent(self.Bg.gameObject, typeof(ImageAlterable))
    if imageAlterable then
        imageAlterable.isNativeSize = false
        imageAlterable:LoadSprite(string.format('uiatlas/trailstage/competition_main_btn_challenge_%d.png', seqNo))
    end
    
    KTool.SetActive(self.CatNode.gameObject, false)
    KTool.SetActive(self.DisableImage.gameObject, self.isLocked)
end

function TrailQuestCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
return TrailQuestCellNode